function contarDuplicados(array) {
  const valoresUnicos = new Set(array);
  return array.length - valoresUnicos.size;
}

console.log(contarDuplicados([1, 2, 2, 3, 4, 4, 4])); // 3

function agruparPorTipo(itens) {
  const grupos = new Map();

  for (const item of itens) {
    const tipo = typeof item;
    if (!grupos.has(tipo)) {
      grupos.set(tipo, []);
    }
    grupos.get(tipo).push(item);
  }

  return grupos;
}

const resultado = agruparPorTipo([1, 'a', true, 2, 'b', { x: 1 }]);
console.log(resultado.get('number'));  // [1, 2]
console.log(resultado.get('string'));  // ['a', 'b']
console.log(resultado.get('boolean')); // [true]

function palavraMaisFrequente(texto) {
  const contagens = new Map();

  for (const palavra of texto.toLowerCase().split(' ')) {
    contagens.set(palavra, (contagens.get(palavra) ?? 0) + 1);
  }

  let melhorPalavra = null;
  let maiorContagem = 0;

  for (const [palavra, contagem] of contagens) {
    if (contagem > maiorContagem) {
      maiorContagem = contagem;
      melhorPalavra = palavra;
    }
  }

  return melhorPalavra;
}

console.log(palavraMaisFrequente('o gato e o cão e o gato dormem'));
// "o"

function contarNos(raiz) {
  const visitados = new WeakSet();

  function visitar(atual) {
    if (visitados.has(atual)) {
      return 0;
    }
    visitados.add(atual);

    let total = 1;
    for (const filho of atual.filhos ?? []) {
      total += visitar(filho);
    }
    return total;
  }

  return visitar(raiz);
}

const folhaA = { filhos: [] };
const folhaB = { filhos: [] };
const ramo = { filhos: [folhaA, folhaB] };
ramo.filhos.push(ramo); // referência circular, aponta para si próprio

console.log(contarNos(ramo)); // 3 (ramo, folhaA, folhaB)
